class pathfinder {
  lastLocation;
  location;
  velocity;
  diameter;
  isFinished;
  constructor() {
    location = new PVector(width/2, height-100);
    lastLocation = new PVector(location.x, location.y);
    velocity = new PVector(0, -10);
    diameter = random(10, 20);
    isFinished = false;
  }
  constructor(pathfinder parent) {
    location = parent.location.get();
    lastLocation = parent.lastLocation.get();
    velocity = parent.velocity.get();
    diameter = parent.diameter * 0.62;
    isFinished = parent.isFinished;
    parent.diameter = diameter;
  }

  function update() {
    if(location.x > -10 & location.x < width + 10 & location.y > -10 & location.y < height + 10) {
      lastLocation.set(location.x, location.y);
      if (diameter > 0.2) {
        count ++;
        let bump = new PVector(random(-1, 1), random(-1, 1));
        velocity.normalize();
        bump.mult(0.2);
        velocity.mult(0.8);
        velocity.add(bump);
        velocity.mult(random(5, 10));
        location.add(velocity);
        if (random(0, 1) < 0.2) { // control length
          paths = (pathfinder[]) append(paths, new constructor(this));
        }
      } else {
        if(!isFinished) {
          isFinished = true;
          noStroke();
          fill(200, 230, 150, 100);
          ellipse(location.x, location.y, 20, 20);
					fill(180,100,0); //; //180,200,0);
					//text("الرحمان",location.x,location.y);
					text(names[int(random(0,99))],location.x,location.y);
          stroke(200, 0, 0); //,200);
        }
      }
    }
  }
}
