function setup() {
  createCanvas(800, 700);
  background(250);
  ellipseMode(CENTER);
	textAlign(CENTER,BOTTOM);
	textSize(8);
  stroke(200, 0, 0, 200);
  smooth();
  num = 2;
  count = 0;
  paths = new Array(num);
  for(i = 0; i < num; i++) paths[i] = new pathfinder();
}

function draw() {
//println(count);
//  println(paths.length);
  for (i = 0; i < paths.length; i++) {
    let loc = paths[i].location;
    let lastLoc = paths[i].lastLocation;
    strokeWeight(paths[i].diameter);
    line(lastLoc.x, lastLoc.y, loc.x, loc.y);
    paths[i].update();
  }
}
function mousePressed() {
  background(250);
  count = 0;
  paths = new Array(num);
  for(i = 0; i < num; i++) paths[i] = new pathfinder();

}

